import java.util.concurrent.locks.ReentrantLock;

// BAD: carrier thread is pinned while blocking on I/O inside the monitor
synchronized (this) {
    jdbcConnection.executeQuery(sql);
}

// GOOD: virtual thread unmounts while waiting; carrier is free
private final ReentrantLock lock = new ReentrantLock();
lock.lock();
try {
    jdbcConnection.executeQuery(sql);
} finally {
    lock.unlock();
}

